test({ sr: 'jedan argument po pozivu', en: 'one argument per call' }, () => {
  const add = curry((a, b, c) => a + b + c);
  expect(add(1)(2)(3)).toBe(6);
});
test({ sr: 'više argumenata odjednom', en: 'several arguments at once' }, () => {
  const add = curry((a, b, c) => a + b + c);
  expect(add(1, 2)(3)).toBe(6);
  expect(add(1)(2, 3)).toBe(6);
  expect(add(1, 2, 3)).toBe(6);
});

