test('partial results are reusable', () => {
  const add = curry((a, b) => a + b);
  const add1 = add(1);
  expect(add1(2)).toBe(3);
  expect(add1(5)).toBe(6);
});
test('a function without parameters is called immediately', () => {
  expect(curry(() => 42)()).toBe(42);
});

